use std::path::Path;

use anyhow::Result;

use crate::apply::ini_utils::{hex_to_rgb_csv, KdeIni};
use crate::apply::ThemePaths;
use crate::color::oklab_blend;
use crate::scheme::MaterialYouScheme;

pub const DARKER_TITLEBAR_RULE_DESCRIPTION: &str =
    "Darker Titlebar - generated by kde-material-you-colors, do not rename";

/// SierraBreeze window button RGB color strings (`r,g,b`), matching `schemeconfigs.py`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SierraBreezeButtonColors {
    pub btn_close_active_color: String,
    pub btn_minimize_active_color: String,
    pub btn_maximize_active_color: String,
    pub btn_keep_above_active_color: String,
    pub btn_keep_below_active_color: String,
    pub btn_on_all_desktops_active_color: String,
    pub btn_shade_active_color: String,
    pub btn_inactive_color: String,
}

/// Compute SierraBreeze active and inactive window button colors (`r,g,b`) for light or dark mode,
/// matching `schemeconfigs.py:635-693`.
pub fn compute_sierra_breeze_colors(
    scheme: &MaterialYouScheme,
    is_light: bool,
) -> SierraBreezeButtonColors {
    let p50 = scheme
        .tones
        .primary
        .get(50)
        .map(String::as_str)
        .unwrap_or("#4285f4");
    let p60 = scheme
        .tones
        .primary
        .get(60)
        .map(String::as_str)
        .unwrap_or("#5e97f6");
    let p70 = scheme
        .tones
        .primary
        .get(70)
        .map(String::as_str)
        .unwrap_or("#8ab4f8");
    let p80 = scheme
        .tones
        .primary
        .get(80)
        .map(String::as_str)
        .unwrap_or("#aecbfa");

    if is_light {
        let cl = &scheme.schemes.light;
        let light_active = cl.get("onBackground").map(String::as_str).unwrap_or("#1f1f1f");
        let light_inactive = cl
            .get("surfaceContainerHighest")
            .map(String::as_str)
            .unwrap_or("#e0e0e0");
        let secondary = cl.get("secondary").map(String::as_str).unwrap_or("#5f6368");

        SierraBreezeButtonColors {
            btn_close_active_color: hex_to_rgb_csv(&oklab_blend(p50, light_active, 0.05)),
            btn_minimize_active_color: hex_to_rgb_csv(&oklab_blend(p60, light_active, 0.05)),
            btn_maximize_active_color: hex_to_rgb_csv(&oklab_blend(p70, light_active, 0.05)),
            btn_keep_above_active_color: hex_to_rgb_csv(&oklab_blend(
                "#118cff",
                light_active,
                0.05,
            )),
            btn_keep_below_active_color: hex_to_rgb_csv(&oklab_blend(
                "#5d00b9",
                light_active,
                0.05,
            )),
            btn_on_all_desktops_active_color: hex_to_rgb_csv(&oklab_blend(
                "#00b9b9",
                light_active,
                0.05,
            )),
            btn_shade_active_color: hex_to_rgb_csv(&oklab_blend("#b900b6", light_active, 0.05)),
            btn_inactive_color: hex_to_rgb_csv(&oklab_blend(light_inactive, secondary, 0.32)),
        }
    } else {
        let cd = &scheme.schemes.dark;
        let dark_active = cd.get("onBackground").map(String::as_str).unwrap_or("#e3e3e3");
        let dark_inactive = cd
            .get("surfaceContainerHighest")
            .map(String::as_str)
            .unwrap_or("#333333");
        let secondary = cd.get("secondary").map(String::as_str).unwrap_or("#bbc7db");

        SierraBreezeButtonColors {
            btn_close_active_color: hex_to_rgb_csv(&oklab_blend(dark_active, p80, 0.7)),
            btn_minimize_active_color: hex_to_rgb_csv(&oklab_blend(dark_active, p70, 0.7)),
            btn_maximize_active_color: hex_to_rgb_csv(&oklab_blend(dark_active, p70, 0.7)),
            btn_keep_above_active_color: hex_to_rgb_csv(&oklab_blend(
                dark_active,
                "#118cff",
                0.7,
            )),
            btn_keep_below_active_color: hex_to_rgb_csv(&oklab_blend(
                dark_active,
                "#5d00b9",
                0.7,
            )),
            btn_on_all_desktops_active_color: hex_to_rgb_csv(&oklab_blend(
                dark_active,
                "#00b9b9",
                0.7,
            )),
            btn_shade_active_color: hex_to_rgb_csv(&oklab_blend(dark_active, "#b900b6", 0.7)),
            btn_inactive_color: hex_to_rgb_csv(&oklab_blend(dark_inactive, secondary, 0.32)),
        }
    }
}

/// Apply SierraBreeze window button colors to `<config_dir>/breezerc` under `[Windeco]`.
pub fn apply_sierra_breeze_button_colors(
    scheme: &MaterialYouScheme,
    is_light: bool,
    breezerc_path: &Path,
) -> Result<SierraBreezeButtonColors> {
    let colors = compute_sierra_breeze_colors(scheme, is_light);
    let mut ini = KdeIni::load_or_default(breezerc_path)?;

    ini.set("Windeco", "ButtonCloseActiveColor", &colors.btn_close_active_color);
    ini.set(
        "Windeco",
        "ButtonMaximizeActiveColor",
        &colors.btn_maximize_active_color,
    );
    ini.set(
        "Windeco",
        "ButtonMinimizeActiveColor",
        &colors.btn_minimize_active_color,
    );
    ini.set(
        "Windeco",
        "ButtonKeepAboveActiveColor",
        &colors.btn_keep_above_active_color,
    );
    ini.set(
        "Windeco",
        "ButtonKeepBelowActiveColor",
        &colors.btn_keep_below_active_color,
    );
    ini.set(
        "Windeco",
        "ButtonOnAllDesktopsActiveColor",
        &colors.btn_on_all_desktops_active_color,
    );
    ini.set("Windeco", "ButtonShadeActiveColor", &colors.btn_shade_active_color);

    ini.set("Windeco", "ButtonCloseInactiveColor", &colors.btn_inactive_color);
    ini.set(
        "Windeco",
        "ButtonMaximizeInactiveColor",
        &colors.btn_inactive_color,
    );
    ini.set(
        "Windeco",
        "ButtonMinimizeInactiveColor",
        &colors.btn_inactive_color,
    );
    ini.set(
        "Windeco",
        "ButtonKeepAboveInactiveColor",
        &colors.btn_inactive_color,
    );
    ini.set(
        "Windeco",
        "ButtonKeepBelowInactiveColor",
        &colors.btn_inactive_color,
    );
    ini.set(
        "Windeco",
        "ButtonOnAllDesktopsInactiveColor",
        &colors.btn_inactive_color,
    );
    ini.set("Windeco", "ButtonShadeInactiveColor", &colors.btn_inactive_color);

    ini.save(breezerc_path)?;
    Ok(colors)
}

/// Apply titlebar opacity (`0..=100`) to `breezerc` (`[Windeco]` `BackgroundOpacity`),
/// `sierrabreezeenhancedrc` (`[Windeco]` `BackgroundOpacity`), and `klassy/klassyrc`
/// (`[TitleBarOpacity]` `ActiveTitleBarOpacity` & `InactiveTitleBarOpacity`).
pub fn apply_titlebar_opacity(
    opacity_light: u32,
    opacity_dark: u32,
    is_light: bool,
    paths: &ThemePaths,
) -> Result<u32> {
    let opacity = if is_light {
        opacity_light.clamp(0, 100)
    } else {
        opacity_dark.clamp(0, 100)
    };
    let opacity_str = opacity.to_string();

    let breezerc_path = paths.breezerc_path();
    let mut breeze_ini = KdeIni::load_or_default(&breezerc_path)?;
    breeze_ini.set("Windeco", "BackgroundOpacity", &opacity_str);
    breeze_ini.save(&breezerc_path)?;

    let sberc_path = paths.sberc_path();
    let mut sbe_ini = KdeIni::load_or_default(&sberc_path)?;
    sbe_ini.set("Windeco", "BackgroundOpacity", &opacity_str);
    sbe_ini.save(&sberc_path)?;

    let klassyrc_path = paths.klassyrc_path();
    let mut klassy_ini = KdeIni::load_or_default(&klassyrc_path)?;
    klassy_ini.set("TitleBarOpacity", "ActiveTitleBarOpacity", &opacity_str);
    klassy_ini.set("TitleBarOpacity", "InactiveTitleBarOpacity", &opacity_str);
    klassy_ini.save(&klassyrc_path)?;

    Ok(opacity)
}

/// Apply Klassy window decoration active/inactive outline colors to `<config_dir>/klassy/klassyrc`
/// matching `titlebar_utils.py:klassy_windeco_outline_color`.
pub fn apply_klassy_windeco_outline(
    scheme: &MaterialYouScheme,
    is_light: bool,
    klassyrc_path: &Path,
) -> Result<(String, String)> {
    let (outline, outline_inactive) = if is_light {
        let cl = &scheme.schemes.light;
        (
            cl.get("primaryFixed")
                .cloned()
                .unwrap_or_else(|| "#d2e3fc".to_string()),
            cl.get("surfaceDim")
                .cloned()
                .unwrap_or_else(|| "#dadce0".to_string()),
        )
    } else {
        let cd = &scheme.schemes.dark;
        (
            cd.get("primaryFixed")
                .cloned()
                .unwrap_or_else(|| "#d2e3fc".to_string()),
            cd.get("surfaceBright")
                .cloned()
                .unwrap_or_else(|| "#3c4043".to_string()),
        )
    };

    let mut klassy_ini = KdeIni::load_or_default(klassyrc_path)?;
    klassy_ini.set(
        "WindowOutlineStyle",
        "ThinWindowOutlineStyleActive",
        "WindowOutlineCustomColor",
    );
    klassy_ini.set(
        "WindowOutlineStyle",
        "ThinWindowOutlineStyleInactive",
        "WindowOutlineCustomColor",
    );
    klassy_ini.set(
        "WindowOutlineStyle",
        "ThinWindowOutlineCustomColorActive",
        &outline,
    );
    klassy_ini.set(
        "WindowOutlineStyle",
        "ThinWindowOutlineCustomColorInactive",
        &outline_inactive,
    );
    klassy_ini.set(
        "WindowOutlineStyle",
        "WindowOutlineCustomColorOpacityActive",
        "100",
    );
    klassy_ini.set(
        "WindowOutlineStyle",
        "WindowOutlineCustomColorOpacityInactive",
        "100",
    );
    klassy_ini.set(
        "WindowOutlineStyle",
        "WindowOutlineStyleActive",
        "WindowOutlineCustomColor",
    );
    klassy_ini.set(
        "WindowOutlineStyle",
        "WindowOutlineStyleInactive",
        "WindowOutlineCustomColor",
    );
    klassy_ini.set(
        "WindowOutlineStyle",
        "WindowOutlineCustomColorActive",
        &outline,
    );
    klassy_ini.set(
        "WindowOutlineStyle",
        "WindowOutlineCustomColorInactive",
        &outline_inactive,
    );

    klassy_ini.save(klassyrc_path)?;
    Ok((outline, outline_inactive))
}

/// Apply KDE Rounded Corners outline colors (`r,g,b`) to `<config_dir>/kwinrc` (`[Round-Corners]`)
/// matching `titlebar_utils.py:kde_rounded_corners_effect_outline_color`.
pub fn apply_kde_rounded_corners_outline(
    scheme: &MaterialYouScheme,
    is_light: bool,
    kwinrc_path: &Path,
) -> Result<(String, String)> {
    let (outline_hex, outline_inactive_hex) = if is_light {
        let cl = &scheme.schemes.light;
        (
            cl.get("primaryFixed")
                .map(String::as_str)
                .unwrap_or("#d2e3fc"),
            cl.get("surfaceDim")
                .map(String::as_str)
                .unwrap_or("#dadce0"),
        )
    } else {
        let cd = &scheme.schemes.dark;
        (
            cd.get("primaryFixed")
                .map(String::as_str)
                .unwrap_or("#d2e3fc"),
            cd.get("surfaceBright")
                .map(String::as_str)
                .unwrap_or("#3c4043"),
        )
    };

    let outline = hex_to_rgb_csv(outline_hex);
    let outline_inactive = hex_to_rgb_csv(outline_inactive_hex);

    let mut kwin_ini = KdeIni::load_or_default(kwinrc_path)?;
    kwin_ini.set("Round-Corners", "OutlineColor", &outline);
    kwin_ini.set("Round-Corners", "InactiveOutlineColor", &outline_inactive);
    kwin_ini.set("Round-Corners", "ActiveOutlineAlpha", "255");
    kwin_ini.set("Round-Corners", "InactiveOutlineAlpha", "255");
    kwin_ini.save(kwinrc_path)?;

    Ok((outline, outline_inactive))
}

/// Create or update the darker titlebar window rule in `<config_dir>/kwinrulesrc`,
/// matching `titlebar_utils.py:kwin_rule_darker_titlebar`.
/// Returns the rule section ID (e.g. `"1"`).
pub fn apply_kwin_darker_titlebar_rule(
    is_light: bool,
    darker_window_list: Option<&str>,
    kwinrulesrc_path: &Path,
) -> Result<String> {
    let raw_list = darker_window_list
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .unwrap_or("--not-configured--");

    let base_scheme_name = if is_light {
        "MaterialYouLight_darker_titlebar"
    } else {
        "MaterialYouDark_darker_titlebar"
    };

    let mut ini = KdeIni::load_or_default(kwinrulesrc_path)?;
    ini.ensure_section("General");

    let mut active_rules: Vec<String> = ini
        .get("General", "rules")
        .unwrap_or("")
        .split(',')
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(ToOwned::to_owned)
        .collect();

    let mut existing_rule_id: Option<String> = None;
    for rule in &active_rules {
        if ini.get(rule, "Description") == Some(DARKER_TITLEBAR_RULE_DESCRIPTION) {
            existing_rule_id = Some(rule.clone());
            break;
        }
    }

    let rule_id = if let Some(id) = existing_rule_id {
        id
    } else {
        let new_id = (active_rules.len() + 1).to_string();
        ini.set("General", "count", &new_id);
        active_rules.push(new_id.clone());
        new_id
    };

    ini.ensure_section(&rule_id);
    ini.set(&rule_id, "Description", DARKER_TITLEBAR_RULE_DESCRIPTION);

    let next_scheme_name = if ini.get(&rule_id, "decocolor") == Some(base_scheme_name) {
        format!("{base_scheme_name}2")
    } else {
        base_scheme_name.to_string()
    };

    ini.set(&rule_id, "decocolor", &next_scheme_name);
    ini.set(&rule_id, "decocolorrule", "2");
    ini.set(&rule_id, "wmclassmatch", "3");
    let wmclass_regex = format!("({})", raw_list.replace(' ', "|"));
    ini.set(&rule_id, "wmclass", &wmclass_regex);

    let rules_csv = active_rules.join(",");
    ini.set("General", "rules", &rules_csv);

    ini.save(kwinrulesrc_path)?;
    Ok(rule_id)
}
